3	  ExecutionContext,
4	  Injectable,
5	  UnauthorizedException,
6	} from '@nestjs/common';
7	import { ConfigService } from '@nestjs/config';
8	import * as jwt from 'jsonwebtoken';
9	import { JwksClient } from 'jwks-rsa';
10	
11	@Injectable()
12	export class JwtGuard implements CanActivate {
13	  private jwksClient: JwksClient;
14	
15	  constructor(private config: ConfigService) {
16	    const supabaseUrl = this.config.getOrThrow('SUPABASE_URL');
17	    this.jwksClient = new JwksClient({
18	      jwksUri: `${supabaseUrl}/auth/v1/.well-known/jwks.json`,
19	      cache: true,
20	      cacheMaxEntries: 5,
21	      cacheMaxAge: 600000,
22	    });
23	  }
24	
25	  async canActivate(context: ExecutionContext): Promise<boolean> {
26	    const request = context.switchToHttp().getRequest();
27	    const authHeader = request.headers['authorization'] as string | undefined;
28	
29	    if (!authHeader?.startsWith('Bearer ')) return false;
30	
31	    const token = authHeader.slice(7);
32	
33	    try {
34	      const decoded = jwt.decode(token, { complete: true });
35	      if (!decoded || typeof decoded === 'string') throw new Error('invalid');
36	
37	      const key = await this.jwksClient.getSigningKey(decoded.header.kid);
38	      const verified = jwt.verify(token, key.getPublicKey()) as jwt.JwtPayload;
39	
40	      request.userId = verified.sub;
41	      request.userRole = verified.user_metadata?.role ?? 'customer';
42	      return true;
43	    } catch {
44	      throw new UnauthorizedException('Token JWT inválido');
45	    }
46	  }
47	}
